#!/usr/bin/env python3
"""Offline, dependency-free feature explorer built from data/features.json."""
import html,json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
items=json.loads((root/'data/features.json').read_text())['features']
summary=json.loads((root/'data/catalog-summary.json').read_text())
# Escape HTML closing marker if it ever occurs in user-generated prose.
blob=json.dumps(items,ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UI4ME Planning Catalogue</title><style>
:root{color-scheme:light dark;--bg:#0e1520;--card:#192333;--text:#eaf2fc;--muted:#b3c2d4;--line:#324458;--blue:#8cc8ff}*{box-sizing:border-box}body{font:15px/1.5 system-ui,Segoe UI,sans-serif;background:var(--bg);color:var(--text);margin:0 auto;max-width:1340px;padding:24px}a{color:var(--blue)}h1{font-size:2.1rem;margin:.15em 0}.intro{color:var(--muted);max-width:950px}.stats{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.stat{background:var(--card);padding:12px 17px;border:1px solid var(--line);border-radius:10px}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0 20px}input,select{background:var(--card);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:11px;font:inherit}input{flex:2;min-width:280px}select{flex:1;min-width:150px}.card{background:var(--card);padding:17px 19px;margin:10px 0;border:1px solid var(--line);border-radius:10px}small,.meta{color:var(--muted)}small{font-size:12px}.meta{margin:4px 0}p{margin:6px 0}.refs{margin-top:12px;padding-top:12px;border-top:1px solid var(--line)}.refs code{font-size:12px;word-break:break-word;color:#d6e8ff}summary{cursor:pointer}.pill{display:inline-block;font-size:12px;padding:1px 7px;border-radius:6px;border:1px solid #53708d;margin-right:5px}#count{color:var(--muted)}@media(prefers-color-scheme:light){:root{--bg:#f6f8fc;--card:#fff;--text:#142133;--muted:#4c5e72;--line:#d7e0ea;--blue:#175f9c}.refs code{color:#123e65}}
</style></head><body><h1>UI4ME roadmap and feature ownership</h1><p class="intro">Frozen research baseline 2026-11-11. Source anchors refer to the original old repository archive, not the current refactored repository. Code presence is not feature qualification. See <a href="README.md">README</a>, <a href="ROADMAP.md">roadmap</a>, <a href="ARCHITECTURE_CHARTER.md">charter</a>, <a href="OLD_SOURCE_TRACEABILITY.md">source methodology</a>.</p>
<div class="stats"><div class="stat"><strong>224</strong><div>Features</div></div><div class="stat"><strong>144</strong><div>Old code anchors</div></div><div class="stat"><strong>5</strong><div>Ownership classes</div></div></div>
<div class="controls"><input id="q" type="search" placeholder="Search feature, owner, acceptance, original source path"><select id="layer"><option value="">All layers</option></select><select id="release"><option value="">All targets</option></select><select id="priority"><option value="">All priorities</option></select><select id="old"><option value="">Old-code evidence: any</option><option value="yes">Has source anchor</option><option value="no">No source anchor</option></select></div><p id="count"></p><div id="results"></div><script>
const data=__DATA__;const elems={q:document.querySelector('#q'),layer:document.querySelector('#layer'),release:document.querySelector('#release'),priority:document.querySelector('#priority'),old:document.querySelector('#old')};
function escapeHtml(x){return String(x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
for(let [k,prop] of [['layer','layer'],['release','target'],['priority','priority']]){for(let v of [...new Set(data.map(x=>x[prop]))].sort()){let o=document.createElement('option');o.value=v;o.textContent=v;elems[k].appendChild(o)}}
function draw(){const q=elems.q.value.trim().toLowerCase();const rows=data.filter(x=>(!elems.layer.value||x.layer===elems.layer.value)&&(!elems.release.value||x.target===elems.release.value)&&(!elems.priority.value||x.priority===elems.priority.value)&&(!elems.old.value||(elems.old.value==='yes'?x.old_refs.length>0:x.old_refs.length===0))&&(!q||JSON.stringify(x).toLowerCase().includes(q)));
document.querySelector('#count').textContent=rows.length+' matching features (out of '+data.length+')';document.querySelector('#results').innerHTML=rows.map(x=>'<article class="card"><strong>'+escapeHtml(x.id)+' · '+escapeHtml(x.title)+'</strong><div class="meta"><span class="pill">'+escapeHtml(x.layer)+'</span><span class="pill">'+escapeHtml(x.target)+'</span><span class="pill">'+escapeHtml(x.priority)+'</span>0.2: '+escapeHtml(x.current_02)+' · donor: '+escapeHtml(x.old_evidence)+'</div><p>'+escapeHtml(x.rationale)+'</p><details><summary>Acceptance, dependencies and source evidence</summary><p><b>Acceptance:</b> '+escapeHtml(x.acceptance)+'</p>'+(x.depends_on.length?'<p><b>Depends on:</b> '+x.depends_on.map(escapeHtml).join(', ')+'</p>':'')+(x.old_refs.length?'<div class="refs"><b>Original donor code (not release evidence):</b>'+x.old_refs.map(r=>'<p><code>'+escapeHtml(r.path)+':'+r.line_start+'–'+r.line_end+'</code><br><small>Matched line '+r.match_line+' — '+escapeHtml(r.match_text)+'; '+r.kind+'; '+r.confidence+'</small></p>').join('')+'</div>':'')+'</details></article>').join('')}
for(let el of Object.values(elems)){el.addEventListener('input',draw);el.addEventListener('change',draw)}draw();
</script></body></html>'''
(root/'INDEX.html').write_text(page.replace('__DATA__',blob),encoding='utf-8')
print('Created offline INDEX.html for',len(items),'features')
